# Compact representation parser to save tokens and construct final dictionary cleanly
def parse_q(tup):
    q_type = tup[0]
    if q_type == "MCQ":
        _, q_en, q_hi, opts_en, opts_hi, ans, sol_en, sol_hi = tup
        return {
            "type": "MCQ",
            "q": q_en,
            "opts": opts_en,
            "ans": ans,
            "sol": sol_en
        }, {
            "type": "MCQ",
            "q": q_hi,
            "opts": opts_hi,
            "ans": ans,
            "sol": sol_hi
        }
    elif q_type == "MCMC":
        _, q_en, q_hi, opts_en, opts_hi, ans, sol_en, sol_hi = tup
        return {
            "type": "Multiple Correct MCQ",
            "q": q_en,
            "opts": opts_en,
            "ans": ans,
            "sol": sol_en
        }, {
            "type": "Multiple Correct MCQ",
            "q": q_hi,
            "opts": opts_hi,
            "ans": ans,
            "sol": sol_hi
        }
    elif q_type == "TF":
        _, q_en, q_hi, ans_bool, sol_en, sol_hi = tup
        return {
            "type": "True/False",
            "q": q_en,
            "opts": ["True", "False"],
            "ans": 0 if ans_bool else 1,
            "sol": sol_en
        }, {
            "type": "True/False",
            "q": q_hi,
            "opts": ["सत्य", "असत्य"],
            "ans": 0 if ans_bool else 1,
            "sol": sol_hi
        }
    elif q_type == "Fill":
        _, q_en, q_hi, ans_en, ans_hi, sol_en, sol_hi = tup
        return {
            "type": "Fill in the Blank",
            "q": q_en,
            "ans": str(ans_en),
            "sol": sol_en
        }, {
            "type": "Fill in the Blank",
            "q": q_hi,
            "ans": str(ans_hi),
            "sol": sol_hi
        }
    elif q_type == "Match":
        _, q_en, q_hi, items_en, items_hi, opts_en, opts_hi, sol_en, sol_hi = tup
        return {
            "type": "Match the Following",
            "q": q_en,
            "items": [{"left": x} for x in items_en],
            "options": [{"val": str(i), "text": opts_en[i]} for i in range(len(opts_en))],
            "sol": sol_en
        }, {
            "type": "Match the Following",
            "q": q_hi,
            "items": [{"left": x} for x in items_hi],
            "options": [{"val": str(i), "text": opts_hi[i]} for i in range(len(opts_hi))],
            "sol": sol_hi
        }
    elif q_type == "OL":
        _, q_en, q_hi, sol_en, sol_hi = tup
        return {
            "type": "One-Liner",
            "q": q_en,
            "sol": sol_en
        }, {
            "type": "One-Liner",
            "q": q_hi,
            "sol": sol_hi
        }
    elif q_type == "AR":
        _, q_en, q_hi, ans, sol_en, sol_hi = tup
        return {
            "type": "Assertion-Reason",
            "q": q_en,
            "opts": EN_AR_OPTS,
            "ans": ans,
            "sol": sol_en
        }, {
            "type": "Assertion-Reason",
            "q": q_hi,
            "opts": HI_AR_OPTS,
            "ans": ans,
            "sol": sol_hi
        }
    elif q_type == "MS":
        _, q_en, q_hi, opts_en, opts_hi, ans, sol_en, sol_hi = tup
        return {
            "type": "Statement-Based",
            "q": q_en,
            "opts": opts_en,
            "ans": ans,
            "sol": sol_en
        }, {
            "type": "Statement-Based",
            "q": q_hi,
            "opts": opts_hi,
            "ans": ans,
            "sol": sol_hi
        }
    return None, None

