     ["Coastal mainland with teak forests", "Strategic island north of Bombay harbor", "Seven small islands in the southern harbor"], 
     ["सागौन के जंगलों के साथ तटीय मुख्य भूमि", "बॉम्बे बंदरगाह के उत्तर में रणनीतिक द्वीप", "दक्षिणी बंदरगाह में सात छोटे द्वीप"], 
