    # 6 One-Liners
    ("OL", 
     "Why did Bahadur Shah allow the Portuguese to build a fort in Diu in 1535?", 
     "बहादुर शाह ने 1535 में पुर्तगालियों को दीव में किला बनाने की अनुमति क्यों दी थी?", 
     "Answer: He needed immediate military help against the invading Mughal army of Humayun. Explanation: It was a strategic defense alliance.", 
     "उत्तर: उन्हें हुमायूँ की आक्रमणकारी मुगल सेना के खिलाफ तत्काल सैन्य सहायता की आवश्यकता थी। विवरण: यह एक रणनीतिक सुरक्षा गठबंधन था।"),
    ("OL", 
     "What physical structure caused the final breakdown of trust in Diu in 1536?", 
     "1536 में दीव में किस भौतिक संरचना के कारण विश्वास पूरी तरह से समाप्त हो गया था?", 
     "Answer: The partition wall built by the Portuguese. Explanation: It separated the fort from the city and angered the Sultan.", 
     "उत्तर: पुर्तगालियों द्वारा बनाई गई विभाजन दीवार। विवरण: इसने किले को शहर से अलग कर दिया और सुल्तान को क्रोधित कर दिया।"),
    ("OL", 
     "Which Ottoman governor was ordered to prepare a fleet to assist Gujarat?", 
     "गुजरात की सहायता के लिए किस ओटोमन गवर्नर को बेड़ा तैयार करने का आदेश दिया गया था?", 
     "Answer: Suleiman Pasha, governor of Egypt. Explanation: He was ordered by Sultan Suleiman the Magnificent to lead the naval campaign.", 
     "उत्तर: सुलेमान पाशा, मिस्र के गवर्नर। विवरण: उन्हें ओटोमन सुल्तान सुलेमान द मैग्नीफिसेंट द्वारा नौसैनिक अभियान का नेतृत्व करने का आदेश दिया गया था।"),
    ("OL", 
     "How did the Mughal Emperor Humayun react to the fortification of Diu?", 
     "मुगल सम्राट हुमायूँ ने दीव की किलेबंदी पर क्या प्रतिक्रिया दी थी?", 
     "Answer: He did not attack Diu, as he was forced to withdraw to the east. Explanation: Rebellions in Bengal distracted him.", 
     "उत्तर: उन्होंने दीव पर आक्रमण नहीं किया, क्योंकि उन्हें पूर्व की ओर हटने के लिए मजबूर होना पड़ा था। विवरण: बंगाल में विद्रोहों ने उनका ध्यान भटका दिया था।"),
    ("OL", 
     "What was the main commercial value of Diu to the Portuguese?", 
     "पुर्तगालियों के लिए दीव का मुख्य व्यावसायिक मूल्य क्या था?", 
     "Answer: It commanded the entrance to the Gulf of Khambhat. Explanation: Controlling Diu allowed them to tax trade from Surat and Cambay.", 
     "उत्तर: यह खंभात की खाड़ी के प्रवेश द्वार को नियंत्रित करता था। विवरण: दीव को नियंत्रित करने से उन्हें सूरत और कैम्बे से व्यापार पर कर लगाने की अनुमति मिली।"),
    ("OL", 
     "Which traditional Malabar enemy of the Portuguese did Bahadur Shah contact for help?", 
     "बहादुर शाह ने सहायता के लिए मालाबार में पुर्तगालियों के किस पारंपरिक दुश्मन से संपर्क किया था?", 
     "Answer: The Zamorin of Calicut. Explanation: The Zamorin was a long-term rival of Portuguese expansion in India.", 
     "उत्तर: कालीकट के ज़मोरिन। विवरण: ज़मोरिन भारत में पुर्तगाली विस्तार के दीर्घकालिक प्रतिद्वंद्वी थे।"),

    # 6 Assertion-Reasons
    ("AR", 
     "Assertion: Bahadur Shah built a counter-wall facing the Portuguese fort in Diu.\nReason: He was deeply alarmed by the partition wall constructed by the Portuguese.", 
     "अभिकथन (A): बहादुर शाह ने दीव में पुर्तगाली किले के सामने एक जवाबी दीवार बनाई।\nकारण (R): वह पुर्तगालियों द्वारा निर्मित विभाजन की दीवार से बहुत चिंतित थे।", 
     0, 
     "The partition wall built by the Portuguese alarmed the Sultan, leading him to construct counter-defenses.", 
     "पुर्तगालियों द्वारा निर्मित विभाजन दीवार ने सुल्तान को चिंतित कर दिया, जिससे उन्होंने जवाबी सुरक्षा दीवारों का निर्माण कराया।"),
    ("AR", 
     "Assertion: Humayun captured Diu Fort from the Portuguese in late 1535.\nReason: Humayun had a superior navy that defeated Governor Nino da Cunha's fleet.", 
     "अभिकथन (A): हुमायूँ ने 1535 के अंत में पुर्तगालियों से दीव किले पर कब्जा कर लिया।\nकारण (R): हुमायूँ के पास एक बेहतर नौसेना थी जिसने गवर्नर नीनो दा कुन्हा के बेड़े को हराया था।", 
     3, 
     "Both statements are false; Humayun never captured Diu and had no significant naval capability in the Arabian Sea.", 
     "दोनों कथन असत्य हैं; हुमायूँ ने कभी दीव पर कब्जा नहीं किया और अरब सागर में उनकी कोई महत्वपूर्ण नौसैनिक क्षमता नहीं थी।"),
    ("AR", 
     "Assertion: Bahadur Shah sent secret letters to the Ottoman Sultan.\nReason: He regretted ceding Diu to the Portuguese and wanted Ottoman naval help to expel them.", 
     "अभिकथन (A): बहादुर शाह ने ओटोमन सुल्तान को गुप्त पत्र भेजे।\nकारण (R): उन्हें पुर्तगालियों को दीव सौंपने पर पछतावा था और वह उन्हें खदेड़ने के लिए ओटोमन नौसैनिक सहायता चाहते थे।", 
     0, 
     "His regret and desire to remove the Portuguese prompted him to seek Ottoman intervention.", 
     "पुर्तगालियों को हटाने के उनके पछतावे और इच्छा ने उन्हें ओटोमन हस्तक्षेप लेने के लिए प्रेरित किया।"),
    ("AR", 
     "Assertion: The partition wall in Diu was demolished by Nino da Cunha in 1536.\nReason: Nino da Cunha wanted to avoid any conflict with the Ottoman Empire.", 
     "अभिकथन (A): दीव में विभाजन की दीवार को 1536 में नीनो दा कुन्हा द्वारा ध्वस्त कर दिया गया था।\nकारण (R): नीनो दा कुन्हा ओटोमन साम्राज्य के साथ किसी भी संघर्ष से बचना चाहते थे।", 
     3, 
     "Both statements are false; da Cunha refused to demolish the wall, and he did not show fear of the Ottomans in his local policy.", 
     "दोनों कथन असत्य हैं; दा कुन्हा ने दीवार को गिराने से इनकार कर दिया, और उन्होंने अपनी स्थानीय नीति में ओटोमन्स के प्रति कोई भय नहीं दिखाया।"),
    ("AR", 
     "Assertion: The customs revenues of Diu were a source of friction between the Sultan and the Portuguese.\nReason: Diu was a major trade hub at the entrance of the Gulf of Khambhat.", 
     "अभिकथन (A): दीव का सीमा शुल्क राजस्व सुल्तान और पुर्तगालियों के बीच घर्षण का एक स्रोत था।\nकारण (R): दीव खंभात की खाड़ी के प्रवेश द्वार पर एक प्रमुख व्यापारिक केंद्र था।", 
     0, 
     "The reason correctly explains why the revenues were valuable enough to cause a major political conflict.", 
     "कारण सही ढंग से स्पष्ट करता है कि राजस्व एक बड़े राजनीतिक संघर्ष का कारण बनने के लिए पर्याप्त मूल्यवान क्यों था।"),
