# Process and insert practice questions
practice_en = []
practice_hi = []
for raw in practice_raw:
    en_q, hi_q = parse_q(raw)
    practice_en.append(en_q)
    practice_hi.append(hi_q)

en_data["practiceQuestions"] = practice_en
hi_data["practiceQuestions"] = practice_hi

# Process and insert mock questions
mock_en = []
mock_hi = []
for raw in mock_raw:
    en_q, hi_q = parse_q(raw)
    mock_en.append(en_q)
    mock_hi.append(hi_q)

en_data["mockTestQuestions"] = mock_en
hi_data["mockTestQuestions"] = mock_hi

